<template>
  <div class="dashboard-shell">
    <aside class="admin-sidebar">
      <router-link to="/" class="admin-brand"><img src="/images/miniverso-logo.png" alt="Miniverso"></router-link>
      <p>PAINEL / ESTÚDIO</p>
      <button v-for="item in nav" :key="item.id" :class="{active:tab===item.id}" @click="tab=item.id"><span>{{ item.number }}</span>{{ item.label }}</button>
      <button class="logout" @click="logout">Sair do painel</button>
    </aside>
    <main class="admin-main">
      <header><div><p class="eyebrow">Controle de missão</p><h1>{{ currentTitle }}</h1></div><span class="system-status"><i/> Protótipo local ativo</span></header>
      <section v-if="tab==='overview'" class="overview">
        <div class="metrics"><article><span>Projetos no portfólio</span><strong>{{ projects.length }}</strong><small>{{ publishedCount }} publicados</small></article><article><span>Clientes em andamento</span><strong>{{ clients.length }}</strong><small>{{ averageProgress }}% de avanço médio</small></article><article><span>Projetos em destaque</span><strong>{{ featuredCount }}</strong><small>na seleção principal</small></article></div>
        <div class="mission-card"><div><p class="eyebrow">Ritmo das entregas</p><h2>Andamento geral</h2></div><div class="orbit-progress" :style="{'--progress':`${averageProgress * 3.6}deg`}"><strong>{{ averageProgress }}%</strong><span>média</span></div></div>
        <div class="activity"><h2>Próximas entregas</h2><article v-for="client in clients" :key="client.id"><div><b>{{ client.cliente }}</b><span>{{ client.projeto }}</span></div><div class="mini-progress"><i :style="{width:`${client.progresso}%`}"/></div><strong>{{ client.progresso }}%</strong></article></div>
      </section>
      <section v-else-if="tab==='projects'" class="projects-admin">
        <div class="section-bar"><p>{{ projects.length }} projetos cadastrados</p><button class="primary" @click="newProject">+ Novo projeto</button></div>
        <div class="project-list"><article v-for="project in projects" :key="project.id"><img :src="project.url_imagem" :alt="project.titulo"><div class="project-copy"><span>{{ project.setor }} / {{ project.categoria }}</span><h2>{{ project.titulo }}</h2><p>{{ project.descricao }}</p><div class="project-actions"><PulseMark v-model="project.destaque" @update:model-value="saveProjects"/><label class="visibility"><input v-model="project.publicado" type="checkbox" @change="saveProjects"> Publicado</label><button @click="editProject(project)">Editar</button></div></div></article></div>
      </section>
      <section v-else class="clients-admin">
        <div class="section-bar"><p>Acompanhamento interno dos projetos dos clientes</p><button class="primary" @click="newClient">+ Novo acompanhamento</button></div>
        <article v-for="client in clients" :key="client.id" class="client-card"><div class="client-heading"><div><span>{{ client.status }}</span><h2>{{ client.cliente }}</h2><p>{{ client.projeto }} · {{ client.etapa }}</p></div><button @click="editClient(client)">Atualizar</button></div><div class="progress-row"><div class="progress-track"><i :style="{width:`${client.progresso}%`}"/></div><strong>{{ client.progresso }}%</strong></div><footer><span>Próximo marco</span><b>{{ client.prazo }}</b></footer></article>
      </section>
    </main>
    <dialog ref="projectDialog" class="admin-dialog" @close="editingProject=null"><form method="dialog" @submit.prevent="saveProject"><header><div><p class="eyebrow">Portfólio</p><h2>{{ editingProject?.id ? 'Editar projeto' : 'Novo projeto' }}</h2></div><button value="cancel" aria-label="Fechar">×</button></header><label>Título<input v-model="projectDraft.titulo" required></label><div class="fields"><label>Setor<input v-model="projectDraft.setor" required></label><label>Categoria<input v-model="projectDraft.categoria" required></label></div><label>Descrição<textarea v-model="projectDraft.descricao" required rows="3"/></label><label>Imagem no projeto<input v-model="projectDraft.url_imagem" required></label><label>Link do projeto<input v-model="projectDraft.url"></label><div class="dialog-actions"><HoldButton v-if="editingProject?.id" @confirm="removeProject"/><button class="primary" type="submit">Salvar alterações</button></div></form></dialog>
    <dialog ref="clientDialog" class="admin-dialog" @close="editingClient=null"><form method="dialog" @submit.prevent="saveClient"><header><div><p class="eyebrow">Acompanhamento</p><h2>{{ editingClient?.id ? 'Atualizar projeto' : 'Novo acompanhamento' }}</h2></div><button value="cancel" aria-label="Fechar">×</button></header><label>Identificação do cliente<input v-model="clientDraft.cliente" required></label><label>Projeto<input v-model="clientDraft.projeto" required></label><div class="fields"><label>Etapa atual<input v-model="clientDraft.etapa" required></label><label>Prazo do marco<input v-model="clientDraft.prazo" required></label></div><label>Progresso: {{ clientDraft.progresso }}%<input v-model.number="clientDraft.progresso" type="range" min="0" max="100"></label><label>Status<select v-model="clientDraft.status"><option>Planejamento</option><option>Em produção</option><option>Em validação</option><option>Concluído</option></select></label><button class="primary" type="submit">Salvar acompanhamento</button></form></dialog>
  </div>
</template>
<script setup>
import { computed, reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import HoldButton from '../components/HoldButton.vue'; import PulseMark from '../components/PulseMark.vue'; import { SESSION_KEY, useProjectStore } from '../utils/projectStore.js';
const router=useRouter(); const store=useProjectStore(); const projects=store.projects; const clients=store.clients; const saveProjects=store.saveProjects; const saveClients=store.saveClients; const tab=ref('overview');
const nav=[{id:'overview',number:'01',label:'Visão geral'},{id:'projects',number:'02',label:'Portfólio'},{id:'clients',number:'03',label:'Projetos de clientes'}];
const currentTitle=computed(()=>nav.find(item=>item.id===tab.value)?.label); const publishedCount=computed(()=>projects.value.filter(p=>p.publicado).length); const featuredCount=computed(()=>projects.value.filter(p=>p.destaque).length); const averageProgress=computed(()=>clients.value.length?Math.round(clients.value.reduce((sum,c)=>sum+c.progresso,0)/clients.value.length):0);
const projectDialog=ref(); const clientDialog=ref(); const editingProject=ref(null); const editingClient=ref(null);
const emptyProject=()=>({titulo:'',setor:'',categoria:'',descricao:'',url_imagem:'/images/miniverso-logo.png',url:'',publicado:false,destaque:false}); const emptyClient=()=>({cliente:'',projeto:'',etapa:'Planejamento',progresso:10,prazo:'',status:'Planejamento'});
const projectDraft=reactive(emptyProject()); const clientDraft=reactive(emptyClient());
const newProject=()=>{editingProject.value={};Object.assign(projectDraft,emptyProject());projectDialog.value.showModal()}; const editProject=(project)=>{editingProject.value=project;Object.assign(projectDraft,project);projectDialog.value.showModal()};
const saveProject=()=>{if(editingProject.value?.id)Object.assign(editingProject.value,projectDraft);else projects.value.unshift({...projectDraft,id:`project-${Date.now()}`});saveProjects();projectDialog.value.close()};
const removeProject=()=>{projects.value=projects.value.filter(p=>p.id!==editingProject.value.id);saveProjects();projectDialog.value.close()};
const newClient=()=>{editingClient.value={};Object.assign(clientDraft,emptyClient());clientDialog.value.showModal()}; const editClient=(client)=>{editingClient.value=client;Object.assign(clientDraft,client);clientDialog.value.showModal()}; const saveClient=()=>{if(editingClient.value?.id)Object.assign(editingClient.value,clientDraft);else clients.value.unshift({...clientDraft,id:`client-${Date.now()}`});saveClients();clientDialog.value.close()};
const logout=()=>{sessionStorage.removeItem(SESSION_KEY);router.push('/login')};
</script>
