.dashboard-shell{grid-template-columns:210px minmax(0,1fr);overflow-x:hidden}.admin-main{min-width:0;padding-inline:clamp(22px,4vw,58px)}.metrics{grid-template-columns:repeat(3,minmax(0,1fr))}.activity h2{font-size:23px;line-height:1.15;letter-spacing:-.02em}
